const $=id=>document.getElementById(id), money=v=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(v);
const palette=[['#0d9bb5','#eaf5f6'],['#16a376','#ecf5e9'],['#789798','#eff2f0'],['#9d9f6c','#f4f3e9']];
let uid=0;
function bottle(p){const [color]=palette[p.cat],n=++uid;return `<svg viewBox="0 0 150 240" role="img" aria-label="Envase ilustrativo de ${p.name}"><defs><linearGradient id="g${n}" x1="0" x2="1"><stop stop-color="#e0eeea"/><stop offset=".28" stop-color="#ffffff"/><stop offset=".7" stop-color="#f7fcfa"/><stop offset="1" stop-color="#b5cdc5"/></linearGradient></defs><ellipse cx="75" cy="227" rx="44" ry="7" fill="#123c3b" opacity=".08"/><rect x="55" y="8" width="40" height="30" rx="5" fill="${color}"/><path d="M53 35h44v19c0 13 26 18 26 45v110c0 10-8 15-17 15H44c-10 0-17-5-17-15V99c0-27 26-32 26-45z" fill="url(#g${n})" stroke="#adcbc3" stroke-width=".6"/><path d="M35 100q0-24 19-32" fill="none" stroke="white" stroke-width="4" opacity=".8"/><rect x="28" y="108" width="94" height="88" rx="2" fill="${color}"/><path d="M28 160q47-18 94 0v36H28z" fill="#123c3b" opacity=".13"/><rect x="39" y="112" width="72" height="45" rx="3" fill="#fff"/><image href="assets/logo.svg" x="43" y="115" width="64" height="36" aria-label="GELD · Cinturón de Orión"/><text x="75" y="173" fill="white" font-family="Arial,sans-serif" font-weight="bold" font-size="10" text-anchor="middle">${p.id}</text><text x="75" y="185" fill="white" font-family="Arial,sans-serif" font-size="6" text-anchor="middle">LÍNEA PROFESIONAL</text><path d="M34 206h80" stroke="#c9dcd5"/></svg>`}
let cat=-1,use='',query='',order='featured',cart=[];
try{const saved=JSON.parse(localStorage.getItem('geld-cart-v1')||'[]');if(Array.isArray(saved))cart=saved.filter(l=>products.some(p=>p.id===l.id&&p.variants[l.v]&&Number.isInteger(l.qty)&&l.qty>0&&l.qty<=999&&(!p.aromas.length||p.aromas.includes(l.aroma))));}catch{}
function save(){try{localStorage.setItem('geld-cart-v1',JSON.stringify(cart));}catch{}$('cartCount').textContent=cart.reduce((a,l)=>a+l.qty,0)}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2200)}
function render(){let list=products.filter(p=>(cat<0||p.cat===cat)&&(!use||p.use===use)&&(`${p.name} ${p.id} ${p.description} ${p.use}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase())));if(order==='asc'||order==='desc')list.sort((a,b)=>(a.variants[0].price-b.variants[0].price)*(order==='asc'?1:-1));if(order==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'es'));
$('filters').innerHTML=['Todo el catálogo',...categories].map((c,i)=>`<button data-cat="${i-1}" class="${cat===i-1?'active':''}" aria-pressed="${cat===i-1}">${c}</button>`).join('');$('resultCount').textContent=`${list.length} productos${use?' · '+use:''}`;$('empty').hidden=!!list.length;$('clearFilters').hidden=cat<0&&!use&&!query;
$('productGrid').innerHTML=list.map(p=>`<article class="product"><button class="productArt" style="--bg:${palette[p.cat][1]}" data-detail="${p.id}" aria-label="Ver ${p.name}"><span class="badge">${categories[p.cat].toUpperCase()}</span>${bottle(p)}</button><div class="productInfo"><small>GELD / ${p.id}</small><button class="nameButton" data-detail="${p.id}"><h3>${p.name}</h3></button><p>${p.description}</p><select aria-label="Presentación de ${p.name}" data-variant="${p.id}">${p.variants.map((v,i)=>`<option value="${i}">${v.label}</option>`).join('')}</select><div class="priceRow"><div><strong data-price="${p.id}">${money(p.variants[0].price)}</strong><small>ANTES DE IVA</small></div><button class="add" data-add="${p.id}" aria-label="Agregar ${p.name}">+</button></div></div></article>`).join('')}
function add(id,v,aroma=''){const p=products.find(p=>p.id===id);aroma=aroma||p.aromas[0]||'';const line=cart.find(l=>l.id===id&&l.v===v&&l.aroma===aroma);if(line){if(line.qty>=999)return toast('Máximo 999 unidades por presentación.');line.qty++}else cart.push({id,v,aroma,qty:1});save();toast('Producto agregado a tu cotización ✓')}
function detail(id){const p=products.find(p=>p.id===id);$('detailBody').innerHTML=`<div class="detailGrid"><div class="detailArt">${bottle(p)}</div><div><p class="eyebrow">${categories[p.cat]} · ${p.id}</p><h2>${p.name}</h2><p>${p.description}</p><label>Presentación<select id="detailVariant">${p.variants.map((v,i)=>`<option value="${i}">${v.label} · ${money(v.price)}</option>`).join('')}</select></label>${p.aromas.length?`<label>Aroma<select id="detailAroma">${p.aromas.map(a=>`<option>${a}</option>`).join('')}</select></label>`:''}<p class="safety">Uso según etiqueta y ficha de seguridad del fabricante. No mezclar productos químicos. ${p.id.startsWith('AE')?'Producto inflamable. ':''}${p.id==='PH5'?'La concentración debe validarse con el fabricante. ':''}Referencia: portafolio 2026, página ${p.page}.</p><button class="primary full" id="detailAdd">Agregar a cotización +</button><p class="subtle">Precios antes de IVA. Envase ilustrativo.</p></div></div>`;$('detailAdd').onclick=()=>{add(id,Number($('detailVariant').value),$('detailAroma')?.value||'');$('detail').close()};$('detail').showModal()}
function renderCart(){let sum=0;$('cartLines').innerHTML=cart.length?cart.map((l,i)=>{const p=products.find(p=>p.id===l.id),v=p.variants[l.v];sum+=v.price*l.qty;return `<div class="cartLine">${bottle(p)}<div class="lineBody"><h3>${p.name}</h3><p>${v.label}${l.aroma?' · '+l.aroma:''}</p><p>${money(v.price)} / unidad</p><div class="qty"><button data-change="${i}" data-delta="-1" aria-label="Reducir ${p.name}">−</button><span>${l.qty}</span><button data-change="${i}" data-delta="1" aria-label="Aumentar ${p.name}">+</button><button class="remove" data-remove="${i}">Quitar</button></div></div><strong class="subtle">${money(v.price*l.qty)}</strong></div>`}).join(''):'<div class="empty">Tu espacio limpio empieza aquí.<br>Agrega productos para preparar tu cotización.</div>';$('cartTotals').innerHTML=`<div class="totalRow"><span>Subtotal antes de IVA</span><strong>${money(sum)}</strong></div><p class="subtle">IVA: por confirmar · Envío: por cotizar</p>`;$('download').disabled=!cart.length;$('emptyCart').hidden=!cart.length}
function reset(){cat=-1;use='';query='';$('search').value='';render()}
$('heroBottles').innerHTML=[products[11],products[0],products[15]].map(bottle).join('');
$('filters').onclick=e=>{const b=e.target.closest('[data-cat]');if(b){cat=Number(b.dataset.cat);use='';render()}};
$('search').oninput=e=>{query=e.target.value;render()};$('sort').onchange=e=>{order=e.target.value;render()};$('clearFilters').onclick=reset;$('resetEmpty').onclick=reset;
document.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{use=b.dataset.use;cat=-1;query='';$('search').value='';render();$('catalogo').scrollIntoView({behavior:'smooth'})});
$('productGrid').onchange=e=>{if(e.target.dataset.variant){const p=products.find(p=>p.id===e.target.dataset.variant);document.querySelector(`[data-price="${p.id}"]`).textContent=money(p.variants[Number(e.target.value)].price)}};
$('productGrid').onclick=e=>{const d=e.target.closest('[data-detail]'),a=e.target.closest('[data-add]');if(d)detail(d.dataset.detail);if(a){const id=a.dataset.add,p=products.find(p=>p.id===id);if(p.aromas.length){detail(id);$('detailVariant').value=document.querySelector(`[data-variant="${id}"]`).value}else add(id,Number(document.querySelector(`[data-variant="${id}"]`).value))}};
$('openCart').onclick=()=>{renderCart();$('cart').showModal()};document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('cartLines').onclick=e=>{const b=e.target.closest('[data-change]'),r=e.target.closest('[data-remove]');if(b){const i=Number(b.dataset.change);cart[i].qty=Math.min(999,cart[i].qty+Number(b.dataset.delta));if(cart[i].qty===0)cart.splice(i,1)}if(r)cart.splice(Number(r.dataset.remove),1);save();renderCart()};$('emptyCart').onclick=()=>{cart=[];save();renderCart()};
$('download').onclick=()=>{const lines=cart.map(l=>{const p=products.find(p=>p.id===l.id),v=p.variants[l.v];return `${p.id} | ${p.name} | ${v.label}${l.aroma?' | '+l.aroma:''} | ${l.qty} und. | ${money(v.price)} c/u | ${money(v.price*l.qty)}`});const total=cart.reduce((s,l)=>s+products.find(p=>p.id===l.id).variants[l.v].price*l.qty,0),text=`GELD - RESUMEN DE COTIZACIÓN (DEMO)\nIndustrias WRX S.A.S. · Portafolio 2026\nFecha: ${new Date().toLocaleDateString('es-CO')}\n\n${lines.join('\n')}\n\nSubtotal antes de IVA: ${money(total)}\nIVA y envío pendientes de confirmación.\n\nSimulación sin validez comercial. No se ha enviado ningún pedido. Precios, disponibilidad y especificaciones deben confirmarse con el proveedor.`,url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='GELD-cotizacion-demo.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Resumen descargado. No se ha enviado ningún pedido.')};save();render();
